/**
 * Возвращает SVG-разметку для иконки по slug.
 * @param string $slug
 * @return string  полный тег <svg> или пустая строка если slug не найден
 */
function evrika_icon_svg($slug) {
    $icons = evrika_get_icons();
    if (empty($slug) || !isset($icons[$slug])) {
        return '';
    }
    return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true">'
        . $icons[$slug]['svg']
        . '</svg>';
}

/**
 * Правильное склонение: 1 товар, 2 товара, 5 товаров
 * @param int $n
 * @return string
 */
function evrika_plural_products($n) {
    if ($n === 0) {
        return 'нет товаров';
    }
    $mod10  = $n % 10;
    $mod100 = $n % 100;
    if ($mod10 === 1 && $mod100 !== 11) {
        $word = 'товар';
    } elseif ($mod10 >= 2 && $mod10 <= 4 && ($mod100 < 10 || $mod100 >= 20)) {
        $word = 'товара';
    } else {
        $word = 'товаров';
    }
    return number_format($n, 0, '.', ' ') . ' ' . $word;
}
